// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Seed the market first so the contract is initialized
        if (c.marketDrugs() == 0) {
            c.seedMarket{value: 1 ether}(1000);
        }

        // Ensure caller has zero Kilos
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.getFreeKilo.selector));
        if (!success) {
            // If revert, rule vacuously true
            assertTrue(true);
            return;
        }

        uint256 timestampAfter = block.timestamp;
        uint256 lastCollect = c.lastCollect(caller);
        assertTrue(lastCollect == timestampAfter);
    }
}

